<script setup lang="ts">
import ImageList from './ImageList.vue'
import ImageListVapor from './ImageListVapor.vue'

import type { TOssImageOptions } from '../lib'
import { ref, shallowRef, computed } from 'vue'

const pageList = shallowRef([
  { name: 'Virtual DOM', component: ImageList },
  { name: 'Vapor Mode', component: ImageListVapor }
])
const pageName = ref('Virtual DOM')
const pageComponent = computed(() => {
  return pageList.value.find(item => item.name === pageName.value)?.component || ImageList
})

const base64Image = 'data:image/jpeg;base64,'
const imageListData = shallowRef<TOssImageOptions[]>([
  'example.jpg',
  { path: 'example.jpg' },
  { path: 'example.jpg', width: 100 },
  { path: 'example.jpg', width: 100, height: 30 },
  { path: 'example.jpg', long: 100 },
  { path: 'example.jpg', short: 30 },
  { path: 'example.jpg', width: 100, quality: 10 },
  { path: 'example.jpg', width: 100, resizeMode: 'lfit' },
  { path: 'example.jpg', width: 100, ratio: 3 },
  { path: 'example.jpg', width: 100, height: 30, resizeMode: 'lfit' },
  { loading: 'https://oss-console-img-demo-cn-hangzhou-3az.oss-cn-hangzhou.aliyuncs.com/example.gif', width: 100, height: 30, resizeMode: 'lfit', ratio: 3 },
  { loading: 'https://oss-console-img-demo-cn-hangzhou-3az.oss-cn-hangzhou.aliyuncs.com/example.gif', path: 'example111.jpg', width: 100, resizeMode: 'lfit', ratio: 4, quality: 10 },
  { loading: 'https://oss-console-img-demo-cn-hangzhou-3az.oss-cn-hangzhou.aliyuncs.com/example.gif', error: 'error.jpg', path: 'example111.jpg', width: 100, resizeMode: 'lfit', ratio: 4, quality: 10 },
  { loading: 'https://oss-console-img-demo-cn-hangzhou-3az.oss-cn-hangzhou.aliyuncs.com/example.gif', path: 'example.jpg', width: 100, resizeMode: 'lfit', ratio: 4, quality: 10 },
  { loading: 'https://oss-console-img-demo-cn-hangzhou-3az.oss-cn-hangzhou.aliyuncs.com/example.gif', path: base64Image, width: 100, resizeMode: 'lfit', ratio: 4, quality: 10 }
])
</script>

<template>
  <div class="app-container">
    <header class="header">
      <h1 class="title">Vue OSS Image Demo</h1>
      <nav class="nav">
        <button
          v-for="item in pageList"
          :key="item.name"
          @click="pageName = item.name"
          :class="['nav-button', { active: pageName === item.name }]"
        >
          {{ item.name }}
        </button>
      </nav>
    </header>

    <main class="main-content">
      <component :is="pageComponent" :listData="imageListData" />
    </main>
  </div>
</template>

